import{_ as o,o as t,c as r,a0 as n}from"./chunks/framework.CLbANrvH.js";const p=JSON.parse('{"title":"What is neuron?","description":"","frontmatter":{"title":"What is neuron?"},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":1791849617000}'),a={name:"guide/intro.md"};function i(s,e,l,d,c,h){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="what-is-neuron" tabindex="-1">What is neuron? <a class="header-anchor" href="#what-is-neuron" aria-label="Permalink to &quot;What is neuron?&quot;">​</a></h1><p><code>neuron</code> is a <strong>library-only</strong> Rust crate that hosts an OpenAI-compatible (and Anthropic Messages v1) inference server inside any Rust embedder process. It loads model weights, runs inference on one of three ML frameworks, and serves the result on a stable HTTP surface — all from inside the host&#39;s own process.</p><h2 id="why-a-library-not-a-standalone-binary" tabindex="-1">Why a library, not a standalone binary? <a class="header-anchor" href="#why-a-library-not-a-standalone-binary" aria-label="Permalink to &quot;Why a library, not a standalone binary?&quot;">​</a></h2><p>Most inference servers (vLLM, ollama, llama.cpp server) are standalone daemons — they bind a port, you point clients at it. That&#39;s the right model for shared GPU servers, but the wrong model for embedding into a desktop app or mobile binary:</p><ul><li><strong>Tauri 2 desktop shell</strong> should ship neuron as part of its binary, not spawn a sidecar process.</li><li><strong>Flutter mobile</strong> (via <code>cargo-ndk</code>) builds neuron into a shared library loaded by a Kotlin/Swift shim.</li><li><strong>Server-side process</strong> like an HTTP gateway or agent orchestrator already has its own main loop — adding a sidecar is friction.</li></ul><p><code>neuron::run_embedded(NeuronEmbedConfig { port: 8085, ... })</code> returns a <code>NeuronHandle</code> that owns the axum server&#39;s lifecycle. The host calls <code>handle.request_shutdown()</code> + <code>handle.join().await</code> for graceful drain. Drop the handle without shutdown and you leak the bind port — the type system enforces correct lifecycle.</p><h2 id="what-it-provides" tabindex="-1">What it provides <a class="header-anchor" href="#what-it-provides" aria-label="Permalink to &quot;What it provides&quot;">​</a></h2><ul><li><strong>6 capability surfaces</strong>: <ul><li><strong>LLM</strong> — Qwen 2/2.5/3/3.5, Llama 2/3, Phi-3, Mistral, ChatGLM (candle); Gemma 3 (litert_lm subprocess); 40+ families (mistralrs engine with PagedAttention + ISQ)</li><li><strong>TTS</strong> — VoxCpm via burn 0.21 (Chinese + English, voice cloning, pre-converted <code>.mpk</code> weights)</li><li><strong>ASR</strong> — Whisper (candle-transformers); MP3 / FLAC / OGG-Vorbis via <code>symphonia</code> when <code>--features asr-audio</code></li><li><strong>Rerank</strong> — BGE / mxbai / jina (candle cross-encoders) + Cohere HTTP proxy</li><li><strong>Embedding</strong> — MiniLM BERT (batched via <code>BatchLongest</code> padding, base64 output)</li><li><strong>Vision</strong> — YOLOv8 / RT-DETR / DETR (candle), RF-DETR / Florence-2 (ONNX pluggable: ort / tract / onnxruntime), with LoRA adapter registration</li></ul></li><li><strong>10+ OpenAI-compatible HTTP routes</strong> + Anthropic Messages v1 at <code>/v1/messages</code></li><li><strong>Multi-source model registry</strong> (HuggingFace, hf-mirror China CDN, ModelScope) with per-engine and per-model source overrides</li><li><strong>Multi-framework engine</strong> — candle (default), burn (TTS), litert_lm (on-device LLM). Pick what fits; opt out of the rest via feature flags.</li><li><strong>Stable, well-defined wire format</strong> — any client that works with OpenAI / vLLM / ollama / llama.cpp server / Anthropic SDK works with neuron unchanged</li></ul><h2 id="what-it-does-not-do" tabindex="-1">What it does NOT do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does NOT do&quot;">​</a></h2><ul><li><strong>No standalone binary</strong> — neuron is <code>crate-type = [&quot;staticlib&quot;, &quot;cdylib&quot;, &quot;rlib&quot;]</code> only. There is no <code>neuron serve</code> CLI. (If you need a standalone server, see the historical <code>prefrontal</code> project&#39;s standalone mode, which is not part of neuron.)</li><li><strong>No SaaS / no telemetry / no phone-home</strong> — neuron never makes outbound network calls except model downloads triggered explicitly via <code>POST /v1/models/pull</code></li><li><strong>No built-in agent loop</strong> — neuron serves inference. You bring your own agent / orchestrator on top of the OpenAI-compatible wire format</li><li><strong>No vector database / no RAG</strong> — neuron does embedding + retrieval-augmented query is the caller&#39;s job. Use the embedding endpoint + your own vector store.</li><li><strong>No model training</strong> — neuron consumes pre-trained weights. Training (LoRA, fine-tune) is out of scope.</li></ul><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><p><code>neuron</code> is released under the <strong>Apache License 2.0</strong>. The vendored VoxCpm implementation under <code>src/tts/voxcpm_burn/</code> and the YOLOv8 architecture in <code>src/vision/yolov8_arch.rs</code> are in-house (clean-room reimplementation) and relicensed to match. Third-party attributions (candle, burn, mistral.rs, litert_lm, axum, tokio, etc.) are documented in <a href="https://github.com/ibloc/neuron/blob/main/LICENSE" target="_blank" rel="noreferrer"><code>LICENSE</code></a>.</p><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/neuron/guide/quick-start">Quick Start</a> — embed neuron in a Rust binary in 20 lines</li><li><a href="/neuron/concepts/architecture">Architecture</a> — data flow, crate layout, trait surface</li><li><a href="/neuron/concepts/capabilities">Capabilities</a> — the 6 model surfaces in detail</li><li><a href="/neuron/concepts/embedding">Embedding in Hosts</a> — concrete Tauri / Flutter / server patterns</li></ul>',14)])])}const g=o(a,[["render",i]]);export{p as __pageData,g as default};
